// Des: First-run setup and manual login
// Flo: login: open the app page, wait until the page is not a login or challenge page; setup: browser > data folder lock > login > doctor > dry demo > consent
// I/O: Ctx (caller) > lines on stdout, consent flag in the state db
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const halt = @import("ru-safe-halt.zig"); const pace = @import("ru-huma-pace.zig"); const priv = @import("ru-safe-priv.zig"); const doct = @import("ru-doct-main.zig"); const disp = @import("ru-jobs-disp.zig");
const CF = .{ .poll = 2000, .minz = 10 };
pub fn loginRun(ctx: *task.Ctx) !void { ctx.page.arm(ctx.conf.brow_time_seco * 1000); try ctx.page.navigate(ctx.aren, ctx.base); task.say(ctx, "log in to Oracle in the browser window (password, Google, GitHub, 2FA by hand). Waiting...", .{}); const tot = @as(u64, ctx.conf.brow_time_seco) * 5000; var wtd: u64 = 0; while (wtd <= tot) { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const urlz = ctx.page.urlNow(ctx.aren) catch ""; const txt = ctx.page.textNow(ctx.aren) catch ""; if (txt.len >= CF.minz and halt.check(urlz, txt, "") == null) { task.say(ctx, "logged in", .{}); return; } pace.nap(ctx.iozz, CF.poll, ctx.conf.time_scal_perc); wtd += CF.poll; } return error.Timeout; }
fn notice(ctx: *task.Ctx) void { task.say(ctx, "Note: driving the Oracle console by program may go against its terms, and a redesign can break steps. You accept this risk.", .{}); task.say(ctx, "To accept and turn on live runs, run: or-orac-webs setup --yes", .{}); }
pub fn setupRun(ctx: *task.Ctx, yes: bool, grant: []const u8, dataroot: []const u8) !void { task.say(ctx, "1/5 browser: found and open", .{}); const locked = priv.lockDown(ctx.gpaz, ctx.iozz, dataroot, grant); task.say(ctx, "2/5 data folder: {s} ({s})", .{ dataroot, if (locked) "owner-only" else "permissions not changed" }); task.say(ctx, "3/5 login", .{}); try loginRun(ctx); task.say(ctx, "4/5 doctor", .{}); _ = doct.doctor(ctx, "", "") catch |err| { if (err != error.Drift) return err; task.say(ctx, "some labels were not found: see above, fix labl_over in aa-conf-main.json (or run: or-orac-webs map)", .{}); }; task.say(ctx, "5/5 dry-run demo (nothing is sent)", .{}); const prev = ctx.mode; ctx.mode = .dry; defer ctx.mode = prev; disp.exec(ctx, "inst-list", .{}) catch |err| task.say(ctx, "demo note: {s}", .{@errorName(err)}); if (yes) { try ctx.store.metaSet("consent", task.nowMs(ctx)); task.say(ctx, "consent saved: live runs are allowed", .{}); } else if (!task.consentOk(ctx)) notice(ctx) else task.say(ctx, "consent already saved", .{}); }
